	/**
	 * Default Constructor
	 */
    public SiteService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SiteEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SiteRepository.class) );
		this.validator		= applicationContext.getBean(SiteValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Site
	 */
		public Site createSite( CreateSiteCommand command ) {

		Site entity = new Site();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSiteId( command.getSiteId() );
            entity.setName( command.getName() );
            entity.setAddress( command.getAddress() );
            entity.setTimezone( command.getTimezone() );
            entity.setLatitude( command.getLatitude() );
            entity.setLongitude( command.getLongitude() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Site {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSiteCommand
	 * @return		Site
	 */
	public Site updateSite( UpdateSiteCommand command ) {

		Site entity = new Site();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSiteId( command.getSiteId() );
            entity.setName( command.getName() );
            entity.setAddress( command.getAddress() );
            entity.setTimezone( command.getTimezone() );
            entity.setLatitude( command.getLatitude() );
            entity.setLongitude( command.getLongitude() );
            entity.setTenant( command.getTenant() );
            entity.setBuildings( command.getBuildings() );
            entity.setDevices( command.getDevices() );
            entity.setGateways( command.getGateways() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Site {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSiteCommand
	 */
	public void delete( DeleteSiteCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSiteId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Site {0} ", id );

	}

	/**
	 * Method to retrieve the Site via SiteFetchOneSummary
	 * @param 	summary SiteFetchOneSummary
	 * @return 	SiteFetchOneResponse
	 */
	public Site getSite( SiteFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SiteFetchOneSummary arg cannot be null" );

		Site entity = null;
		UUID id = summary.getSiteId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Site using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Sites
	 *
	 * @return 	List<Site>
	 */
    public List<Site> getAllSite() {
		List<Site> list = projector.findAll( new FindAllSiteQuery() );
		return list;
	}

	/**
	 * assign Tenant on Site
	 * @param		command AssignTenantToSiteCommand
	 */
	public void assignTenant( AssignTenantToSiteCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignTenant(command.getSiteId(), command.getAssignment());

	}

	/**
	 * unAssign Tenant on Site
	 * @param		command UnAssignTenantFromSiteCommand
	 */
	public void unAssignTenant( UnAssignTenantFromSiteCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignTenant(command.getSiteId());
	}
	

